// 自动生成: 内联前端页面（exe 打包时直接 require）
// 源文件: src/public/index.html, 修改页面后请重新运行 tools/regen-inline.js
module.exports = "<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"utf-8\"/>\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"/>\n<meta http-equiv=\"Cache-Control\" content=\"no-cache, no-store, must-revalidate\">\n<meta http-equiv=\"Pragma\" content=\"no-cache\">\n<meta http-equiv=\"Expires\" content=\"0\">\n<title>Momo传值助手 · 让ERP在中国普遍成功</title>\n<style>\n:root{\n  --bg:#0f172a;--card:#1e293b;--card2:#172033;--line:#2d3a4f;\n  --acc:#38bdf8;--ok:#22c55e;--warn:#ef4444;--text:#e2e8f0;--muted:#94a3b8;\n  --input:#0b1220;--radius:8px;\n}\n*{box-sizing:border-box;}\nbody{font-family:\"Segoe UI\",system-ui,-apple-system,sans-serif;background:var(--bg);color:var(--text);margin:0;padding:0;}\n\n/* ===== header ===== */\n.app-header{background:var(--card);border-bottom:2px solid var(--acc);padding:18px 24px 14px;}\n.app-header h1{font-size:20px;margin:0 0 4px;color:var(--acc);letter-spacing:.3px;}\n.app-header .subtitle{font-size:12px;color:var(--muted);line-height:1.8;}\n\n/* ===== main container ===== */\n.container{max-width:1200px;margin:0 auto;padding:20px 24px 40px;}\n\n/* ===== conn banner ===== */\n#connBanner{border-radius:var(--radius);padding:11px 64px;margin-bottom:16px;font-size:13px;line-height:1.5;\n  position:relative;background:var(--input);border:1px solid var(--line);text-align:center;}\n#connBannerText{display:block;text-align:center;font-size:13px;font-weight:500;}\n#connBanner button#btnReconnect{display:none;margin:0 auto;padding:4px 12px;font-size:12px;position:static;}\n#connBanner.loading .banner-row{text-align:center;}\n#connBanner.err button#btnReconnect{display:inline-block;margin:8px auto 0;}\n#connBanner .gx-mark{position:absolute;right:14px;top:50%;transform:translateY(-50%);font-size:12px;color:#64748b;font-weight:700;letter-spacing:1px;}\n\n/* ===== tabs ===== */\n.tabbar{display:flex;gap:0;border-bottom:2px solid var(--line);margin-bottom:20px;}\n.tabbtn{background:none;border:none;color:var(--muted);font:600 14px 'Segoe UI',sans-serif;\n  padding:10px 20px;cursor:pointer;border-bottom:2px solid transparent;transition:color .15s,border-color .15s;}\n.tabbtn:hover{color:var(--text);}\n.tabbtn.active{color:var(--acc);border-bottom-color:var(--acc);}\n\n/* ===== card ===== */\n.card{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:20px;margin-bottom:16px;}\n.card-title{font-size:13px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.5px;margin-bottom:14px;\n  padding-bottom:8px;border-bottom:1px solid var(--line);}\n\n/* ===== labels & inputs ===== */\nlabel.lbl{display:block;font-size:12px;color:var(--muted);margin-bottom:6px;font-weight:600;letter-spacing:.2px;}\nselect,input[type=text],input[type=password]{width:100%;padding:9px 12px;border:1px solid var(--line);border-radius:6px;\n  background:var(--input);color:var(--text);font-size:14px;outline:none;transition:border-color .15s;}\nselect:focus,input[type=text]:focus,input[type=password]:focus{border-color:var(--acc);}\nselect:disabled,input[type=text]:disabled,input[type=password]:disabled{opacity:.5;cursor:not-allowed;}\n\n/* ===== grid ===== */\n.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:14px;}\n.grid3{display:grid;grid-template-columns:1fr 1fr 1fr;gap:14px;margin-bottom:14px;}\n.sub{font-size:11px;color:#64748b;margin-top:4px;}\n\n/* ===== checkbox ===== */\n.chk{font-size:13px;color:var(--muted);display:inline-block;margin-right:16px;}\n.chk input{vertical-align:middle;margin-right:6px;accent-color:var(--acc);}\n\n/* ===== buttons ===== */\n.btn{background:var(--acc);color:#000;border:none;padding:9px 20px;border-radius:6px;cursor:pointer;\n  font-size:14px;font-weight:600;transition:opacity .15s,background .15s;}\n.btn:hover{opacity:.85;}\n.btn.primary{background:var(--ok);}\n.btn.danger{background:var(--warn);color:#fff;}\n.btn:disabled{opacity:.4;cursor:not-allowed;}\n.btn.sm{padding:6px 12px;font-size:12px;}\n\n/* ===== value toolbar ===== */\n.action-panel{grid-column:1/-1;background:var(--input);border:1px solid var(--line);border-radius:8px;padding:12px;margin:16px 0;}\n.action-main{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap;}\n.action-settings,.action-buttons{display:flex;align-items:center;gap:10px;flex-wrap:wrap;}\n.action-panel .chk{margin:0;white-space:nowrap;}\n\n/* ===== status ===== */\n.status{font-size:13px;margin:12px 0;display:block;}\n.status.ok{color:var(--ok);}\n.status.err{color:var(--warn);}\n\n/* ===== pre / code ===== */\npre{background:var(--input);padding:12px;border-radius:6px;font-size:12px;overflow-x:auto;\n  color:var(--muted);white-space:pre-wrap;word-break:break-word;margin:8px 0;border:1px solid var(--line);}\ncode{font-family:Consolas,\"Courier New\",monospace;font-size:12px;color:var(--acc);}\n\n/* ===== table ===== */\ntable{width:100%;border-collapse:collapse;font-size:12px;margin-top:8px;}\nth,td{padding:8px 10px;border-bottom:1px solid var(--line);text-align:left;}\nth{color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.3px;}\ntr:hover td{background:rgba(56,189,248,.04);}\n\n/* ===== tags ===== */\n.tag{display:inline-block;padding:2px 8px;border-radius:4px;font-size:11px;\n  background:var(--input);border:1px solid var(--line);margin:0 6px 4px 0;color:var(--acc);}\n\n/* ===== summary box ===== */\n.summary{background:var(--input);border:1px solid var(--line);border-radius:6px;padding:12px 16px;margin-bottom:10px;font-size:13px;line-height:1.8;}\n.summary b{color:var(--acc);}\n\n/* ===== main table box ===== */\n.maintbl{display:flex;align-items:center;gap:8px;background:var(--input);border:1px solid var(--line);\n  border-radius:6px;padding:8px 12px;margin:8px 0;font-size:12px;flex-wrap:wrap;}\n.maintbl .lbl2{color:var(--muted);font-weight:600;}\n.maintbl .val{color:var(--acc);font-family:Consolas,monospace;}\n.arrow{color:var(--warn);font-weight:700;}\n\n/* ===== disabled state ===== */\n.disabled{opacity:.4;pointer-events:none;}\n\n/* ===== combobox ===== */\n.combobox{position:relative;}\n.cb-list{display:none;position:absolute;top:100%;left:0;right:0;background:var(--input);\n  border:1px solid var(--line);border-radius:0 0 6px 6px;max-height:220px;overflow-y:auto;z-index:30;\n  box-shadow:0 6px 18px rgba(0,0,0,.4);}\n.cb-list.open{display:block;}\n.cb-item{padding:8px 12px;font-size:13px;cursor:pointer;border-bottom:1px solid var(--card);color:var(--text);}\n.cb-item small{color:var(--muted);margin-left:8px;font-family:Consolas,monospace;}\n.cb-item:hover,.cb-item.active{background:var(--card);color:var(--acc);}\n.cb-item .desc{display:block;color:#64748b;font-size:11px;margin-top:2px;}\n\n/* ===== trigger table ===== */\n.trig-table th,.trig-table td{vertical-align:middle;}\n.trig-table .badge{display:inline-block;padding:2px 8px;border-radius:4px;font-size:11px;font-weight:600;}\n.trig-table .badge.on{background:rgba(34,197,94,.15);color:var(--ok);}\n.trig-table .badge.off{background:rgba(239,68,68,.15);color:var(--warn);}\n\n/* ===== chain row ===== */\n.chainrow{display:grid;grid-template-columns:1.2fr 1fr 1fr 1fr auto;gap:6px;margin-bottom:6px;}\n.chainrow input{padding:8px 10px;}\n.chainrow .btn{align-self:center;}\n\n/* ===== responsive ===== */\n@media(max-width:768px){\n  .grid3{grid-template-columns:1fr;}\n  .grid{grid-template-columns:1fr;}\n  .container{padding:16px;}\n}\n\n/* ===== 数据库连接网格 ===== */\n.conn-grid{display:grid;grid-template-columns:1.2fr 1fr 1fr 1.4fr;gap:14px;margin-bottom:10px;align-items:end;}\n.conn-field{display:flex;flex-direction:column;}\n.conn-field-wide{grid-column:span 1;}\n.pass-wrap{position:relative;display:block;height:40px;}\n.pass-wrap input{padding-right:36px !important;height:40px !important;}\n.pass-toggle{position:absolute;right:8px;top:50%;transform:translateY(-50%);\n  background:transparent;border:none;color:#64748b;font-size:11px;cursor:pointer;\n  padding:4px 6px;letter-spacing:.3px;transition:color .15s;height:24px;line-height:1;}\n.pass-toggle:hover{color:var(--acc);}\n\n/* ===== 整体微调 ===== */\n.card{padding:18px 20px 16px;}\n.card-title{margin-bottom:12px;}\n\n@media(max-width:900px){\n  .conn-grid{grid-template-columns:repeat(2,1fr);}\n}\n\n#connServer,#connUser,#connPass,select#connDbSel{\n  background-color:var(--input) !important;background-image:none !important;\n  border:1px solid var(--line) !important;color:var(--text) !important;}\n#connServer:focus,#connUser:focus,#connPass:focus,#connDbSel:focus:focus{\n  background-color:var(--input) !important;border-color:var(--acc) !important;outline:none;}\n#connServer:active,#connUser:active,#connPass:active{background-color:var(--input) !important;}\n#connServer option,#connDbSel option{background-color:var(--card);color:var(--text);}\n/* datalist 弹层跟随深色（Chromium） */\ninput:-webkit-autofill{-webkit-box-shadow:0 0 0 1000px var(--input) inset !important;-webkit-text-fill-color:var(--text) !important;}\ninput:-webkit-autofill:hover{-webkit-box-shadow:0 0 0 1000px var(--input) inset !important;}\ninput:-webkit-autofill:focus{-webkit-box-shadow:0 0 0 1000px var(--input) inset !important;border-color:var(--acc) !important;}\n\n#connServer,#connUser,#connPass,.pass-wrap input{height:40px;padding:0 12px;}\n\n/* ===== 干跑预览 ===== */\n.pv-wrap{background:var(--input);border:1px solid var(--line);border-radius:8px;padding:20px 22px;margin-top:8px;}\n.pv-head{display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap;\n  padding-bottom:14px;border-bottom:1px solid var(--line);}\n.pv-title{font-size:14px;font-family:Consolas,monospace;color:var(--text);line-height:1.8;word-break:break-all;}\n.pv-target{color:var(--acc);font-weight:600;}\n.pv-arrow{color:var(--muted);margin:0 6px;}\n.pv-source{color:#7dd3fc;}\n.pv-count{font-size:12px;color:var(--muted);white-space:nowrap;letter-spacing:.3px;}\n.pv-count b{font-size:24px;color:var(--ok);margin-right:6px;font-weight:700;}\n.pv-tags{margin-top:14px;display:flex;flex-wrap:wrap;gap:8px;}\n.pv-tags .tag{margin:0;}\n.tag-blue{background:rgba(56,189,248,.08);border-color:rgba(56,189,248,.3);color:#7dd3fc;}\n.pv-table-wrap{margin-top:16px;max-height:420px;overflow:auto;border:1px solid var(--line);border-radius:6px;}\n.pv-table{margin:0;font-size:13px;}\n.pv-table thead th{position:sticky;top:0;background:var(--card2);z-index:2;}\n.pv-table td{padding:10px 12px;}\n.pv-table tbody tr:nth-child(even) td{background:rgba(255,255,255,.02);}\n.pv-mono{font-family:Consolas,monospace;color:var(--text);}\n.pv-cur{color:var(--muted);}\n.pv-new{color:var(--ok);font-weight:700;font-family:Consolas,monospace;}\n.pv-empty{margin-top:16px;padding:28px 20px;border:1px dashed var(--line);border-radius:6px;color:var(--muted);font-size:13px;text-align:center;}\n.pv-foot{margin-top:10px;font-size:11px;color:var(--muted);}\n</style>\n</head>\n<body>\n\n<main class=\"container\">\n<div style=\"text-align:center;padding:14px 0 10px;font-size:13px;color:var(--muted);letter-spacing:.5px;font-weight:500\">科技不是高高在上，而是服务于人民</div>\n\n<div id=\"connBanner\" class=\"loading\"><div class=\"banner-row\"><span id=\"connBannerText\">正在连接数据库...</span><button id=\"btnReconnect\" class=\"btn sm\" type=\"button\" style=\"display:none\">重新连接</button></div><span class=\"gx-mark\">GX</span></div>\n\n<!-- 数据库连接管理 -->\n<div class=\"card\" id=\"dbConnCard\">\n  <div class=\"card-title\">数据库连接</div>\n  <div class=\"conn-grid\">\n    <div class=\"conn-field\">\n      <label class=\"lbl\">服务器</label>\n      <input type=\"text\" id=\"connServer\" style=\"font-family:Consolas,monospace\" autocomplete=\"off\" placeholder=\"输入服务器地址\">\n    </div>\n    <div class=\"conn-field\">\n      <label class=\"lbl\">账号</label>\n      <input type=\"text\" id=\"connUser\" style=\"font-family:Consolas,monospace\" autocomplete=\"off\">\n    </div>\n    <div class=\"conn-field\">\n      <label class=\"lbl\">密码</label>\n      <div class=\"pass-wrap\">\n        <input type=\"password\" id=\"connPass\" style=\"font-family:Consolas,monospace\" autocomplete=\"off\">\n        <button id=\"btnTogglePass\" type=\"button\" title=\"显示/隐藏密码\" class=\"pass-toggle\">显示</button>\n      </div>\n    </div>\n    <div class=\"conn-field conn-field-wide\">\n      <label class=\"lbl\">账套（数据库）</label>\n      <div style=\"display:flex;gap:6px;align-items:center\">\n        <select id=\"connDbSel\" style=\"flex:1\"></select>\n        <button class=\"btn sm\" id=\"btnLoadDbs\" type=\"button\" title=\"刷新账套列表\">刷新</button>\n      </div>\n    </div>\n  </div>\n  <div style=\"display:flex;gap:10px;margin-top:14px;flex-wrap:wrap;align-items:center\">\n    <button class=\"btn sm\" id=\"btnTestConn\" type=\"button\">测试连接</button>\n    <button class=\"btn sm\" id=\"btnSaveConfig\" type=\"button\" title=\"将当前连接参数保存到配置文件\">保存配置</button>\n    <span id=\"connMetaNote\" style=\"font-size:11px;color:#64748b\"></span>\n  </div>\n  <div style=\"margin-top:6px;font-size:11px;color:#475569\">提示：连接参数来自配置文件，修改后点「保存配置」即可持久化。换电脑时修改服务器地址即可。</div>\n</div>\n\n<div id=\"tab-sync\">\n<div class=\"card\">\n  <div class=\"card-title\">跨表带值</div>\n  <div class=\"grid3\">\n    <div>\n      <label class=\"lbl\">① 单据（主表）</label>\n      <select id=\"docSel\"></select>\n      <div class=\"sub\" id=\"docSub\"></div>\n      <div class=\"maintbl\" id=\"mainBox\">\n        <span class=\"lbl2\">主表</span>\n        <span class=\"val\" id=\"mainTbl\">—</span>\n        <span class=\"arrow\">→</span>\n        <span class=\"lbl2\">取</span>\n        <span class=\"val\" id=\"subTbl\">—</span>\n      </div>\n    </div>\n    <div>\n      <label class=\"lbl\">② 目标列（要写入哪一列）</label>\n      <div class=\"combobox\">\n        <input type=\"text\" id=\"fTgt\" placeholder=\"搜索目标列...\" autocomplete=\"off\"\n          onclick=\"openCb('fTgt','cbTgt')\" oninput=\"openCb('fTgt','cbTgt')\" onfocus=\"openCb('fTgt','cbTgt')\" onblur=\"setTimeout(()=>closeCb('cbTgt'),150)\">\n        <div id=\"cbTgt\" class=\"cb-list\"></div>\n      </div>\n      <div class=\"sub\" id=\"tgtSub\"></div>\n    </div>\n    <div id=\"srcWrap\">\n      <label class=\"lbl\">③ 来源档（自动排除已选单据）</label>\n      <select id=\"srcSel\" class=\"disabled\"></select>\n    </div>\n    <div id=\"src2Wrap\" style=\"display:none\">\n      <label class=\"lbl\">③½ 来源档②（可选·链式取值）</label>\n    </div>\n  </div>\n  <div class=\"grid\">\n    <div id=\"valWrap\">\n      <label class=\"lbl\">④ 来源值列（取哪一列的值，可搜索切换）</label>\n      <div class=\"combobox\">\n        <input type=\"text\" id=\"fVal\" placeholder=\"先选择来源档，再选来源值列...\" autocomplete=\"off\"\n          onclick=\"openCb('fVal','cbVal')\" oninput=\"openCb('fVal','cbVal')\" onfocus=\"openCb('fVal','cbVal')\" onblur=\"setTimeout(()=>closeCb('cbVal'),150)\">\n        <div id=\"cbVal\" class=\"cb-list\"></div>\n      </div>\n      <div class=\"sub\" id=\"valSub\"></div>\n      <div id=\"val2Wrap\" style=\"display:none\">\n      <div style=\"margin-top:8px\">\n        <label class=\"chk\" style=\"display:inline\"><input type=\"checkbox\" id=\"chkAllVals\" checked onchange=\"onSrcChange()\"> 显示全部列（默认只显示常用列）</label>\n      </div>\n    </div>\n    \n  </div>\n  <div class=\"action-panel\">\n    <div class=\"action-main\">\n      <div class=\"action-settings\">\n        <label class=\"chk\"><input type=\"checkbox\" id=\"chkForce\"> 强制覆盖</label>\n        <label class=\"chk\"><input type=\"checkbox\" id=\"chkCreateTrigger\"> 建立触发器</label>\n        <label class=\"chk\"><input type=\"checkbox\" id=\"chkMergeDisplay\"> 合并显示</label>\n      </div>\n      <div class=\"action-buttons\">\n        <button class=\"btn\" id=\"btnPreview\">干跑预览</button>\n        <button class=\"btn primary\" id=\"btnExec\">执行（先备份）</button>\n        <button class=\"btn danger\" id=\"btnClearTarget\" type=\"button\" title=\"只清空当前选择的单据+目标列，清空前自动备份\">清空目标列</button>\n        <button class=\"btn\" id=\"btnBackupDir\" type=\"button\" title=\"选择或修改数据库备份路径\">备份路径</button>\n      </div>\n    </div>\n  </div>\n  <div class=\"sub\" id=\"backupDirNote\" style=\"margin-top:-6px\">备份路径：读取中...</div>\n  <span class=\"status\" id=\"status\"></span>\n  <div id=\"result\"></div>\n</div>\n</div>\n\n<!-- ============ 已建立触发器 ============ -->\n<div class=\"card\" style=\"margin-top:16px\">\n  <div class=\"card-title\" style=\"cursor:pointer\" id=\"trigPanelTitle\">▼ 已建立触发器（点击展开）</div>\n  <div id=\"trigPanelBody\" style=\"display:none\">\n    <div style=\"display:flex;gap:8px;margin-bottom:12px;align-items:center;\">\n      <button class=\"btn sm\" id=\"trigRefresh\">刷新列表</button>\n      <span class=\"sub\">来自数据库 sys.triggers（父对象 = 用户表）。</span>\n    </div>\n    <div class=\"sub\" id=\"trigDbNote\" style=\"margin-bottom:8px;\"></div>\n    <span class=\"status\" id=\"trigStatus\"></span>\n    <div id=\"trigList\"><div class=\"sub\">点击刷新查看触发器列表</div></div>\n  </div>\n</div>\n\n</main>\n\n<div id=\"firstOpenModal\" style=\"display:none;position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:9999;align-items:center;justify-content:center;\">\n  <div style=\"background:var(--card);border:1px solid var(--line);border-radius:8px;padding:28px 36px;min-width:320px;text-align:center;box-shadow:0 10px 40px rgba(0,0,0,.5);\">\n    <div style=\"font-size:15px;color:var(--text);margin-bottom:22px;line-height:1.8;\">科技不是高高在上，而是服务于人民</div>\n    <button class=\"btn\" id=\"firstOpenOk\" type=\"button\">确定</button>\n  </div>\n</div>\n\n<script>\n// API 适配层: 浏览器用 fetch\n(function(){\n  const F = {\n    getMeta: async ()=>{\n      // 重试机制：兼容服务刚启动时连接池未就绪（首次 /api/meta 可能 500）\n      for (let attempt=0; attempt<6; attempt++) {\n        try {\n          const r = await fetch(\"/api/meta\");\n          const d = await r.json();\n          if (r.ok && d.docs && d.srcs) return { ok:true, data:d };\n          if (r.ok) return { ok:true, data:d };\n        } catch (_) {}\n        if (attempt < 5) await new Promise(res => setTimeout(res, 2000));\n      }\n      throw new Error('/api/meta 多次重试仍失败，请点「重新连接」');\n    },\n    run: async b=>{ const r=await fetch(\"/api/run\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify(b)}); const d=await r.json(); return d.error?{ok:false,error:d.error}:{ok:true,data:d}; },\n    listTriggers: async ()=>{ const r=await fetch(\"/api/triggers\"); return { ok:true, data: await r.json() }; },\n    buildTrigger: async b=>{ const r=await fetch(\"/api/triggers/build\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify(b)}); const d=await r.json(); return d.error?{ok:false,error:d.error}:{ok:true,data:d}; },\n    createTrigger: async b=>{ const r=await fetch(\"/api/triggers/create\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify(b)}); const d=await r.json(); return d.error?{ok:false,error:d.error}:{ok:true,data:d}; },\n    toggleTrigger: async b=>{ const r=await fetch(\"/api/triggers/toggle\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify(b)}); const d=await r.json(); return d.error?{ok:false,error:d.error}:{ok:true,data:d}; },\n    dropTrigger: async b=>{ const r=await fetch(\"/api/triggers/drop\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify(b)}); const d=await r.json(); return d.error?{ok:false,error:d.error}:{ok:true,data:d}; },\n    testDb: async (b)=>{ try{ const r=await fetch(\"/api/test-conn\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify(b||{})}); return await r.json(); }catch(e){ return {ok:false,error:e.message}; } },\n    listDatabases: async ()=>{ const r=await fetch(\"/api/databases\"); return { ok:true, data: await r.json() }; },\n    switchDb: async b=>{ const r=await fetch(\"/api/switch-db\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify(b)}); const d=await r.json(); return d.ok?{ok:true,data:d}:{ok:false,error:d.error}; },\n    getConfig: async ()=>{ return {ok:true,data:{db:{server:\"browser\", database:\"DSB\"}, backupDir:\"\"}}; },\n    saveConfig: async b=>{ try { const r = await fetch(\"/api/save-config\", {method:\"POST\", headers:{\"Content-Type\":\"application/json\"}, body:JSON.stringify(b||{})}); return await r.json(); } catch(e){ return {ok:false, error:e.message}; } },\n    reconnect: async ()=>{ return {ok:true,data:{}}; }\n  };\n  window.chuanzhi = window.chuanzhi || F;\n})();\n\nwindow.__backupDir = 'D:\\\\TPA\\\\SQL2008';\nlet META=null;\nlet lastPreviewKey=null;\nfunction reqKey(b){ const c={...b}; delete c.confirm; return JSON.stringify(c); }\n\n// ---- 服务器历史（localStorage，可跨重启记忆，最多10条）----\nfunction getSrvHist(){ try{ return JSON.parse(localStorage.getItem('momo_svr_hist')||'[]'); }catch(_){ return []; } }\nfunction rememberSrv(){ const inp=document.getElementById('connServer'); const v=(inp&&inp.value||'').trim(); if(!v) return; let h=getSrvHist(); if(h.indexOf(v)<0){ h.unshift(v); h=Array.from(new Set(h)).slice(0,20); try{localStorage.setItem('momo_svr_hist',JSON.stringify(h));}catch(_){} } }\nasync function dropSrv(key){\n  try{ await fetch('/api/creds/drop',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key:key})}); }catch(_){}\n  try{ let h=getSrvHist().filter(x=>x!==key); localStorage.setItem('momo_svr_hist',JSON.stringify(h)); }catch(_){}\n  try{ let m=JSON.parse(localStorage.getItem('momo_conn_cred')||'{}'); delete m[key]; localStorage.setItem('momo_conn_cred',JSON.stringify(m)); }catch(_){}\n  const inp=document.getElementById('connServer'); if(inp && inp.value.trim()===key) inp.value='';\n  rememberSrv();\n}\n\n\n// ---- 连接凭据记忆：服务器 → {user, pass} ----\nfunction getCred(){ let base={}; try{ base=JSON.parse(localStorage.getItem('momo_conn_cred')||'{}'); }catch(_){ base={}; } if(window.__creds) for(const k in window.__creds){ if(!base[k]) base[k]=window.__creds[k]; } return base; }\nasync function rememberCred(){\n  const s=(document.getElementById('connServer')||{}).value.trim();\n  const u=(document.getElementById('connUser')||{}).value.trim();\n  const p=(document.getElementById('connPass')||{}).value;\n  if(!s&&!u&&!p) return;\n  let m=getCred(); if(s) m[s]={user:u,pass:p};\n  try{ localStorage.setItem('momo_conn_cred',JSON.stringify(m)); }catch(_){}\n  try{ const _body={}; if(s)_body[s]={user:u,pass:p}; if(u||p)_body._last={user:u,pass:p}; await fetch('/api/creds/save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(_body)}); }catch(_){}\n}\nfunction applyCred(sv){\n  const m=getCred(); const c=m[sv]; if(!c) return;\n  const ue=document.getElementById('connUser'); if(ue&&c.user) ue.value=c.user;\n  const pe=document.getElementById('connPass'); if(pe&&c.pass) pe.value=c.pass;\n}\nlet tgtCols=[], valCols=[];\n\nfunction esc(s){return String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));}\n\n// 列号友好标签\nfunction labelOf(col, desc, vals){\n  if (vals && vals[col]) return vals[col];\n  const m = String(col||'').match(/^([A-Z]{3})(9\\d{2})$/);\n  if (m){\n    const n = parseInt(m[2].slice(1), 10);\n    if (n >= 1 && n <= 5)   return '系统字段' + m[2];\n    if (n >= 60 && n <= 75) return '自定文字' + (n - 59);\n    if (n >= 80 && n <= 95) return '自定数字' + (n - 79);\n    if (n >= 96 && n <= 99) return '保留列' + m[2];\n    if (n === 79) return '其他979';\n    return '列' + m[2];\n  }\n  return col + (desc ? '（' + desc + '）' : '');\n}\n\nasync function init(){\n  META=await (await window.chuanzhi.getMeta()).data;\n  const ds=document.getElementById('docSel');\n  ds.innerHTML=''; // 重新加载时先清空，避免重复追加\n  const dph=document.createElement('option'); dph.value=''; dph.textContent='—— 请选择单据 ——'; ds.appendChild(dph);\n  ds.onchange=()=>{ onDocChange(); };\n  const infoGroup=document.createElement('optgroup'); infoGroup.label='信息档';\n  META.docs.forEach(d=>{\n    const o=document.createElement('option');\n    o.value=d.id; o.textContent=d.name;\n    if(d.info) infoGroup.appendChild(o); else ds.appendChild(o);\n  });\n  if(infoGroup.children.length) ds.appendChild(infoGroup);\n}\n\nfunction commonCols(cols, src){\n  const ids = src && src.vals ? Object.keys(src.vals) : [];\n  const sys = cols.filter(c=>!String(c.col).includes('9')).slice(0,6).map(c=>c.col);\n  const keep = new Set([...ids, ...sys]);\n  return cols.filter(c=>keep.has(c.col) || String(c.col).includes('96'));\n}\n\nfunction openCb(fid, listId){\n  const input=document.getElementById(fid);\n  const list=document.getElementById(listId);\n  const q=input.value.toUpperCase();\n  let cols; let srcs; let valsMap={};\n  if(listId==='cbTgt'){ cols=tgtCols;\n    if(!cols.length){ list.innerHTML='<div class=\"cb-item\" style=\"color:#64748b\">（请先选择单据）</div>';list.classList.add('open');return; } }\n  else { srcs=currentSrc(); cols=valCols; valsMap=srcs?.vals||{};\n    if(!document.getElementById('chkAllVals').checked) cols=commonCols(cols,srcs); }\n  list.innerHTML='';\n  if(!cols||!cols.length){\n    const msg = listId==='cbVal' && !currentSrc() ? '（请先选择来源档）' : '（暂无可选项）';\n    list.innerHTML='<div class=\"cb-item\" style=\"color:#64748b\">'+msg+'</div>';\n    list.classList.add('open');\n    return;\n  }\n  cols.filter(c=>c.col.toUpperCase().includes(q)\n    ||(c.desc||'').toUpperCase().includes(q)\n    ||labelOf(c.col,c.desc,valsMap).toUpperCase().includes(q))\n    .forEach(c=>{\n      const div=document.createElement('div');\n      div.className='cb-item';\n      const L=labelOf(c.col,c.desc,valsMap);\n      div.innerHTML='<b>'+esc(L)+'</b><small>'+esc(c.col)+'</small>'+(c.desc&&c.desc!==L?'<span class=\"desc\">'+esc(c.desc)+'</span>':'');\n      div.onmousedown=(e)=>{ e.preventDefault(); pickCb(fid,listId,c.col); };\n      list.appendChild(div);\n    });\n  if(!list.children.length){ list.innerHTML='<div class=\"cb-item\" style=\"color:#64748b\">（暂无数据，请先选择单据）</div>'; }\n  list.classList.add('open');\n}\n\nfunction closeCb(listId){ const l=document.getElementById(listId); if(l) l.classList.remove('open'); }\n\nfunction openCb2(fid,listId){\n  const input=document.getElementById(fid);\n  const list=document.getElementById(listId);\n  const q=input.value.toUpperCase();\n  const src2=currentSrc2();\n  const cols=(META.srcAllCols?.[src2?.id])||[];\n  list.innerHTML='';\n  if(!cols.length){ list.innerHTML='<div class=\"cb-item\" style=\"color:#64748b\">（请先选择来源档②）</div>';list.classList.add('open');return; }\n  cols.filter(cc=>cc.col.toUpperCase().includes(q)||(cc.desc||'').toUpperCase().includes(q))\n    .forEach(cc=>{\n      const div=document.createElement('div');\n      div.className='cb-item';\n      div.innerHTML='<b>'+esc(cc.col)+'</b>'+(cc.desc?'<span class=\"desc\">'+esc(cc.desc)+'</span>':'');\n      div.onmousedown=(e)=>{ e.preventDefault(); document.getElementById(fid).value=cc.col; closeCb(listId); };\n      list.appendChild(div);\n    });\n  list.classList.add('open');\n}\n\nfunction pickCb(fid,listId,col){\n  document.getElementById(fid).value=col;\n  closeCb(listId);\n  if(listId==='cbVal') refreshJoin();\n}\n\nfunction currentSrc(){ return META?.srcs.find(s=>s.id===document.getElementById('srcSel').value); }\nfunction currentSrc2(){ return null; }\n\nfunction updateTriggerEligibility(){\n  const chk=document.getElementById('chkCreateTrigger');\n  if(!chk)return;\n  const docId=document.getElementById('docSel')?.value;\n  const srcId=document.getElementById('srcSel')?.value;\n  const blocked=docId==='YSFGQB' && (srcId==='DCSHDA'||srcId==='DCSHDB');\n  chk.disabled=blocked;\n  if(blocked){ chk.checked=false; chk.title='付款单身汇总依赖付款冲账档，保存后使用执行更新'; }\n  else chk.title='';\n}\n\nfunction refreshSrc2Sub(){\n  const src2=currentSrc2();\n  const el=document.getElementById('src2Sub');\n  if(!src2){ el.textContent='未启用链式取值（来源档②留空）'; return; }\n  const src=currentSrc();\n  el.textContent=src?'将先取 '+src2.id+' 的某一列 → 作为 '+src.id+' 的关联键':'请先选择③来源档';\n}\n\nfunction onDocChange(){\n  if(!META || !Array.isArray(META.srcs)){\n    document.getElementById('docSub').textContent='正在加载单据字典，请稍候...';\n    return;\n  }\n  const doc=META?.docs.find(d=>d.id===document.getElementById('docSel').value);\n  if(!doc)return;\n  document.getElementById('docSub').textContent=doc.sub+' · 品号列 '+(doc.refCol||doc.keyCol)+' · '+(doc.party==='supplier'?'供应商':doc.party==='customer'?'客户':'无')+'侧';\n  document.getElementById('mainTbl').textContent=doc.main+'.'+doc.mainKeyCol;\n  document.getElementById('subTbl').textContent=doc.sub+'.'+doc.keyCol;\n\n  tgtCols=(META.tgtAllCols?.[doc.id])||[];\n  document.getElementById('fTgt').value='';\n  document.getElementById('tgtSub').textContent='共 '+tgtCols.length+' 个可选目标列（请选择）';\n\n  const ss=document.getElementById('srcSel');\n  ss.innerHTML='';\n  ss.disabled=false;\n  ss.classList.remove('disabled');\n  const ph=document.createElement('option'); ph.value=''; ph.textContent='—— 请选择来源档 ——'; ss.appendChild(ph);\n  const exSet=new Set((META.srcExcluded||{})[doc.id]||[]);\n  // 业务流向：上游单据不能取下游单据的值，后台自动排除\n  const infoGroup=document.createElement('optgroup'); infoGroup.label='信息档';\n  META.srcs.forEach(src=>{\n    if(exSet.has(src.id))return;      // 业务流向：下游单据自动排除\n    if(src.id===doc.id)return;        // 来源档不能与主表是同一张表\n    const o=document.createElement('option');\n    o.value=src.id; o.textContent=src.name;\n    if(src.info) infoGroup.appendChild(o); else ss.appendChild(o);\n  });\n  if(infoGroup.children.length) ss.appendChild(infoGroup);\n  if(ss.options.length<=1){ const vs=document.getElementById('valSub'); if(vs) vs.textContent='当前单据没有可选来源档'; }\n  ss.onchange=()=>onSrcChange();\n  onSrcChange();\n\n  // 字典加载成功后清除\"等待数据库连接\"的提示\n  const st=document.getElementById('status');\n  if(st && String(st.textContent).indexOf('等待数据库连接')===0){ st.className='status'; st.textContent=''; }\n}\n\nfunction updatePartyAuto(){\n  const doc=META?.docs.find(d=>d.id===document.getElementById('docSel').value);\n  const src=currentSrc();\n  const chk=document.getElementById('chkParty');\n  const lbl=document.getElementById('partyLabel');\n  if(!doc||!src){\n    if(lbl) lbl.textContent='加 供应商/客户 维度';\n    return;\n  }\n  const canParty = src.party!=='none' && doc.partyCol;\n  chk.checked = canParty;\n  if(lbl){\n    if(canParty){\n      lbl.textContent='加 供应商/客户 维度（已自动匹配：'+(src.party==='supplier'?'供应商':'客户')+'侧）';\n    } else if(src.party==='none'){\n      lbl.textContent='加 供应商/客户 维度（当前来源档无维度）';\n    } else if(!doc.partyCol){\n      lbl.textContent='加 供应商/客户 维度（当前单据无对方列）';\n    } else {\n      lbl.textContent='加 供应商/客户 维度';\n    }\n  }\n}\n\nfunction onSrcChange(){\n  const src=currentSrc();\n  const doc=META?.docs.find(d=>d.id===document.getElementById('docSel').value);\n  updateTriggerEligibility();\n  const fv=document.getElementById('fVal');\n  if(!src){\n    valCols=[];\n    if(fv){ fv.value=''; fv.placeholder='先选择来源档，再选来源值列...'; }\n    const vs=document.getElementById('valSub'); if(vs) vs.textContent='请先选择来源档';\n    return;\n  }\n  valCols=(META.srcAllCols?.[src.id])||[];\n  if(fv){ fv.value=''; fv.placeholder='搜索来源值列...'; }\n  document.getElementById('valSub').textContent='共 '+valCols.length+' 个可选值列（默认关联 '+(src.vals?.[src.valDefault]||src.valDefault)+'）';\n  \n  refreshJoin();\n\n  // Auto chain recommendation for warehouse-based sources\n  autoChainRecommend(src, doc);\n}\n\nfunction autoChainRecommend(src, doc){\n}\n\nfunction refreshJoin(){\n  const doc=META?.docs.find(d=>d.id===document.getElementById('docSel').value);\n  const src=currentSrc();\n  if(!doc||!src)return;\n  const joins=['品号: '+src.key[0]+' = '+(doc.refCol||doc.keyCol)];\n  if(src.party!=='none' && doc.partyCol){ const pfx=src.id.slice(3,6); const partyCol=pfx+'002'; joins.push('对方: '+partyCol+' = m.'+doc.partyCol+' （后台自动）'); }\n  const src2=currentSrc2();\n  if(src2){ joins.unshift('链式: '+src2.id+' → '+src.id+'（来源值列② 关联 来源值列①）'); }\n  const _js=document.getElementById('joinSub'); if(_js) _js.textContent=''; // JOIN 条件由后台自动判断，前台不再展示\n}\n\nfunction curReq(){\n  const docId=document.getElementById('docSel').value;\n  const tgtCol=document.getElementById('fTgt').value.trim();\n  const srcId=document.getElementById('srcSel').value;\n  const srcValCol=document.getElementById('fVal').value.trim();\n  const partyKey=1; // 后台自动判断，前台无需手动勾选\n  if(!docId){alert('请先选择单据');return null;}\n  if(!tgtCol||!srcValCol){alert('请填写目标列和来源值列');return null;}\n  const src2Id=document.getElementById('srcSel2')?document.getElementById('srcSel2').value:'';\n  const src2ValCol=document.getElementById('fVal2')?document.getElementById('fVal2').value.trim():'';\n  if(src2Id && !src2ValCol){alert('已启用来源档②（链式取值），请同时填写 来源值列②');return null;}\n  const forceEl=document.getElementById('chkForce');\n  const trigEl=document.getElementById('chkCreateTrigger');\n  const mergeEl=document.getElementById('chkMergeDisplay');\n  if(mergeEl?.checked){\n    if(!trigEl?.checked){alert('合并显示需要先勾选“建立触发器”');return null;}\n  }\n  const src2Meta=META?.srcs?.find(x=>x.id===src2Id);\n  const s2Key=src2Meta?src2Meta.key[0]:(src2Id.slice(3,6)+String.fromCharCode(48)+String.fromCharCode(49));\n  // 链式取值由后台自动判断，前台不再手动指定 srcJoinKey（避免用错列）\n  const chain=src2Id?{src2Id,src2ValCol,src2Key:s2Key}:null;\n    return {docId,tgtCol,srcId,srcValCol,partyKey,mode:'fill',force:forceEl?forceEl.checked:false,chain,createTrigger:!!trigEl&&trigEl.checked,forceCreateTrigger:false,mergeDisplay:!!mergeEl?.checked,triggerTimeMode:'none',mappings:[]};\n}\n\n// 干跑预览结果渲染\nfunction renderPreview(b, d){\n  const total = d.totalRows ?? 0;\n  const rows = (d.sample || []).map(s => {\n    const cur = (s['现值'] === null || s['现值'] === undefined || s['现值'] === '') ? '—' : esc(s['现值']);\n    const val = (s['应带'] === null || s['应带'] === undefined || s['应带'] === '') ? '—' : esc(s['应带']);\n    return '<tr>'\n      + '<td class=\"pv-mono\">' + esc(s['单号'] ?? '') + '</td>'\n      + '<td class=\"pv-mono\">' + esc(s['序号'] ?? '') + '</td>'\n      + '<td class=\"pv-cur\">' + cur + '</td>'\n      + '<td class=\"pv-new\">' + val + '</td>'\n      + '</tr>';\n  }).join('');\n\n  const tags = '';\n\n  const body = total > 0\n    ? '<div class=\"pv-table-wrap\"><table class=\"pv-table\"><thead><tr>'\n      + '<th>单号</th><th style=\"width:90px\">序号</th><th>现值</th><th>应带</th>'\n      + '</tr></thead><tbody>' + rows + '</tbody></table></div>'\n      + (total > 50 ? '<div class=\"pv-foot\">仅显示前 50 行，实际共 ' + total + ' 行</div>' : '')\n    : '<div class=\"pv-empty\">没有需要填入的行：目标列可能已有值（数值 0 也算已有值，需要覆盖请勾选“强制覆盖”），或来源单据没有匹配数据。</div>';\n\n  return '<div class=\"pv-wrap\">'\n    + '<div class=\"pv-head\">'\n    +   '<div class=\"pv-title\"><span class=\"pv-target\">' + esc(b.docId) + '.' + esc(b.tgtCol) + '</span>'\n    +     '<span class=\"pv-arrow\">←</span><span class=\"pv-source\">' + esc(b.srcId) + '.' + esc(b.srcValCol) + '</span></div>'\n    +   '<div class=\"pv-count\"><b>' + total + '</b><span>行待填入</span></div>'\n    + '</div>'\n    + (tags ? '<div class=\"pv-tags\">' + tags + '</div>' : '')\n    + (d.typeWarning ? '<div style=\"margin:8px 0;padding:8px 10px;border-left:3px solid #f59e0b;background:rgba(245,158,11,.08);color:#fbbf24;font-size:12px;line-height:1.6\">⚠ ' + esc(d.typeWarning) + '</div>' : '')\n    + (d.chainWarning ? '<div style=\"margin:8px 0;padding:8px 10px;border-left:3px solid #38bdf8;background:rgba(56,189,248,.08);color:#7dd3fc;font-size:12px;line-height:1.6\">ⓘ ' + esc(d.chainWarning) + '</div>' : '')\n    + body\n    + '</div>';\n}\n\nasync function doRun(confirm){\n  const b=curReq(); if(!b)return;\n  if(confirm && lastPreviewKey && lastPreviewKey!==reqKey(b)){\n    alert('配置已经变化，请重新预览后再执行。');\n    return;\n  }\n  b.confirm=confirm;\n  const status=document.getElementById('status');\n  status.className='status'; status.textContent=confirm?'执行中（备份+写库）...':'干跑预览中...';\n  let d;\n  try {\n    d = await window.chuanzhi.run(b);\n    if (d && d.data) d = d.data;\n    if (confirm) console.log('[run result]', d);\n  } catch(e) {\n    status.className='status err'; status.textContent='请求失败：'+e.message;\n    return;\n  }\n  document.getElementById('result').innerHTML='';\n  if(d.error){status.className='status err';status.textContent=d.error;return;}\n  status.className='status ok';\n  if(d.preview){\n    lastPreviewKey=reqKey(b);\n    status.textContent='预览完成：共 '+(d.totalRows??0)+' 行待填入，审阅后点「执行（先备份）」。';\n    document.getElementById('result').innerHTML=renderPreview(b,d);\n  } else {\n    lastPreviewKey=null;\n    const aff = (d.affected !== undefined && d.affected !== null) ? d.affected : 0;\n    const cleared = (d.cleared !== undefined && d.cleared !== null) ? d.cleared : 0;\n    const bp = d.backupPath || '未知路径';\n    status.textContent='完成：清空旧值 '+cleared+' 行 · 更新 '+aff+' 行 · 备份 '+bp;\n    let trigMsg = '';\n    if(b.createTrigger && d.triggerResult){\n      if(d.triggerResult.skipped){\n        const forceHint = d.triggerResult.allowForce ? '<br><span style=\"color:#94a3b8\">勾选「强制创建」可忽略此冲突。</span>' : '';\n        trigMsg = '<div style=\"margin-top:8px;padding:8px 12px;background:rgba(245,158,11,.1);border:1px solid rgba(245,158,11,.3);border-radius:6px;color:#f59e0b;font-size:12px\">⚠ '+esc(d.triggerResult.note||'检测到系统冲突，已跳过建立触发器')+forceHint+'</div>';\n      } else if(d.triggerResult.conflict && d.triggerResult.conflict.length){\n        trigMsg = '<div style=\"margin-top:8px;color:#22c55e\">✓ 触发器已创建：'+esc(d.triggerResult.name)+'</div>'\n          + '<div style=\"margin-top:4px;padding:6px 10px;background:rgba(245,158,11,.08);border:1px solid rgba(245,158,11,.25);border-radius:6px;color:#f59e0b;font-size:11px\">⚠ '+esc(d.triggerResult.conflictNote||('系统触发器 '+d.triggerResult.conflict.join('、')+' 也在写此列'))+'</div>';\n      } else if(d.triggerResult.ok){\n        trigMsg = '<div style=\"margin-top:8px;color:#22c55e\">✓ 触发器已创建：'+esc(d.triggerResult.name)+'</div>';\n      } else {\n        trigMsg = '<div style=\"margin-top:8px;color:#ef4444\">✗ 触发器创建失败：'+esc(d.triggerResult.error||'未知错误')+'</div>';\n      }\n    }\n    document.getElementById('result').innerHTML=`\n      <div class=\"summary\"><b>已写入数据库</b> 受影响 <span style=\"color:#22c55e\">${aff}</span> 行 · 备份文件 <code>${esc(bp)}</code></div>\n      <div><b>执行后抽样（前 20）</b>\n        <table><thead><tr><th>单号</th><th>已填值</th></tr></thead><tbody>\n        ${(d.sampleAfter||[]).map(s=>'<tr><td>'+esc(s.docNo)+'</td><td style=\"white-space:pre-wrap\"><b style=\"color:#22c55e\">'+esc(s.filled)+'</b></td></tr>').join('')}\n        </tbody></table>\n      </div>\n      ${trigMsg}\n      <div class=\"sub\" style=\"margin-top:8px\">⚠ 前台易助需<b style=\"color:#ef4444\">关闭该单后重新查询</b>才会显示新值（前台读缓存）。</div>`;\n  }\n}\n\ndocument.getElementById('btnPreview').onclick=()=>doRun(false);\n\ndocument.getElementById('btnClearTarget').onclick=async ()=>{\n  const docId=document.getElementById('docSel').value;\n  const tgtCol=document.getElementById('fTgt').value.trim();\n  if(!docId){alert('请先选择单据');return;}\n  if(!tgtCol){alert('请先选择目标列');return;}\n  const status=document.getElementById('status');\n  status.className='status'; status.textContent='正在统计待清空行...';\n  try{\n    const pv=await (await fetch('/api/clear-target',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({docId,tgtCol,confirm:false})})).json();\n    if(pv.error){status.className='status err';status.textContent=pv.error;return;}\n    if(!pv.totalRows){status.className='status ok';status.textContent='目标列没有非空值，无需清空。';return;}\n    const bd=pv.backupDir||window.__backupDir||'';\n    if(!confirm('将清空 '+docId+'.'+tgtCol+' 的 '+pv.totalRows+' 行非空值。\\n清空前会自动备份到：'+bd+'\\n\\n只清空这一列，不删单据、不动其他字段。确认继续？')){status.textContent='已取消清空。';return;}\n    status.textContent='正在备份并清空...';\n    const r=await (await fetch('/api/clear-target',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({docId,tgtCol,confirm:true})})).json();\n    if(r.error){status.className='status err';status.textContent=r.error;return;}\n    status.className='status ok';\n    status.textContent='已清空 '+docId+'.'+tgtCol+'：'+r.affected+' 行 · 备份 '+(r.backupPath||'未知路径');\n  }catch(e){status.className='status err';status.textContent='清空失败：'+e.message;}\n};\ndocument.getElementById('btnExec').onclick=async ()=>{\n  const curDb=document.getElementById('connDbSel')?document.getElementById('connDbSel').value:'DSB';\n  // 实时取当前生效的备份目录（弹窗选完目录后写进 config.js，这里立即读最新值）\n  let bd=window.__backupDir||'D:\\\\TPA\\\\SQL2008';\n  try{\n    const cr=await (await fetch('/api/config')).json();\n    if(cr&&cr.backupDir){ bd=cr.backupDir; window.__backupDir=bd; }\n  }catch(_){}\n  if(!confirm('确认执行写库？'+(document.getElementById('chkForce')?.checked?'强制覆盖会先清空目标列所有旧值，再填匹配行。':'')+'\\n工具会先自动备份 '+curDb+' 到 '+bd+'\\\\'))return;\n  doRun(true);\n};\n\n// ---- 连接状态 banner ----\nasync function loadConnBanner(){\n  const el=document.getElementById(\"connBanner\");\n  const txt=document.getElementById(\"connBannerText\");\n  const btn=document.getElementById(\"btnReconnect\");\n  el.className=\"loading\";\n  if(txt) txt.textContent='等待数据库连接...';\n\n  // 还没保存服务器时属于\"等待填写\"，不发起连接检测，避免显示成错误\n  let cfg={};\n  try{ cfg=(await (await fetch('/api/config')).json())||{}; }catch(_){ cfg={}; }\n  if(!cfg.server){\n    el.className=\"loading\";\n    if(txt) txt.innerHTML='<b>等待数据库连接</b> · 请填写服务器、账号、密码后点「测试连接」';\n    if(btn) btn.style.display=\"none\";\n    return;\n  }\n\n  // 只信 /api/meta：有 docs 才算真连上，消除 banner 与字典状态脱节\n  let m;\n  try{ m=await (await fetch('/api/meta')).json(); }catch(_){ m={}; }\n  if(m.docs){\n    el.className=\"ok\";\n    if(txt) txt.innerHTML='<b style=\"color:#22c55e\">数据库已连接</b> · 服务器 <code>'+esc(m.server||'-')+'</code> · 账套 <code>'+esc(m.currentDb||'-')+'</code>';\n    if(btn) btn.style.display=\"none\";\n  } else {\n    el.className=\"err\";\n    const msg=m.error||'未知错误';\n    if(txt) txt.innerHTML='<b style=\"color:#ef4444\">数据库连接失败</b>：'+esc(msg)+'。点\"重新连接\"重试。';\n    if(btn) btn.style.display=\"\";\n  }\n}\n\n// ---- 数据库连接管理 ----\nasync function initDbConn(){\n  const r = await window.chuanzhi.listDatabases();\n  const sel = document.getElementById(\"connDbSel\");\n  if (r.ok) {\n    if (!r.data || r.data.error) {\n      sel.innerHTML = '<option value=\"\">（等待连接）</option>';\n      document.getElementById(\"connMetaNote\").textContent = '等待填写数据库连接信息';\n      document.getElementById(\"connMetaNote\").style.color = '#64748b';\n      return;\n    }\n    const dbs = r.data.databases || [];\n    const cur = r.data.currentDb;\n    sel.innerHTML = dbs.map(d =>\n      '<option value=\"'+esc(d.name)+'\"'+(d.name===cur?' selected':'')+'>'+esc(d.name)+'</option>'\n    ).join('');\n    window.__curDb = cur;\n    window.__curDb = cur;\n    document.getElementById(\"connMetaNote\").textContent =\n      '服务器 '+esc(r.data.server)+' · 共 '+dbs.length+' 个账套';\n  } else {\n    sel.innerHTML = '<option value=\"\">（无法加载账套列表）</option>';\n    document.getElementById(\"connMetaNote\").textContent = r.error;\n  }\n}\n// 服务器变化：拉该服务器账套；有保存的偏好账套则回填，否则选第一个（不自动测连）\nasync function onServerChanged() {\n  const sv = document.getElementById('connServer').value.trim();\n  const us = document.getElementById('connUser').value.trim();\n  const pw = document.getElementById('connPass').value;\n  if (!sv) return;\n  // 记住用户当前选中的账套，刷新列表后优先保留，避免点「测试连接」被重置到第一个账套\n  const sel = document.getElementById('connDbSel');\n  const prevDb = sel ? sel.value : '';\n  let r;\n  try {\n    const resp = await fetch('/api/databases', { method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({server:sv, user:us, password:pw}) });\n    r = await resp.json();\n  } catch (e) { r = { ok:false, error:e.message }; }\n  const note = document.getElementById('connMetaNote');\n  if (r.ok || r.databases) {\n    const dbs = r.databases || [];\n    sel.innerHTML = dbs.map(d => '<option value=\"'+d.name+'\">'+d.name+'</option>').join('') || '<option value=\"\">&nbsp;</option>';\n    const pref = (window.__prefs && window.__prefs[sv] && window.__prefs[sv].db);\n    let pick = -1;\n    let kept = '';\n    if (prevDb) { pick = dbs.findIndex(x => x.name === prevDb); if (pick >= 0) kept = prevDb; }\n    if (pick < 0 && pref) { pick = dbs.findIndex(x => x.name === pref); if (pick >= 0) kept = pref; }\n    if (pick < 0 && sel.options.length > 0) pick = 0;\n    if (pick >= 0) sel.selectedIndex = pick;\n    note.textContent = '已识别 ' + sv + ' 的 ' + dbs.length + ' 个账套' + (kept ? '，保留当前账套 ' + kept : '，已选中第一个');\n    note.style.color = '#22c55e';\n    loadConnBanner();\n  } else {\n    note.textContent = '无法连接 ' + sv + '：' + (r.error || '登录失败');\n    note.style.color = '#ef4444';\n  }\n}\ndocument.getElementById(\"btnLoadDbs\").onclick = async () => {\n  const sel = document.getElementById(\"connDbSel\");\n  const note = document.getElementById(\"connMetaNote\");\n  const sv = document.getElementById(\"connServer\").value.trim();\n  const us = document.getElementById(\"connUser\").value.trim();\n  const pw = document.getElementById(\"connPass\").value;\n  const apply = (d, src) => {\n    if (d.ok) {\n      const dbs = d.databases || [];\n      const cur = d.currentDb || '';\n      sel.innerHTML = dbs.map(x =>\n        '<option value=\"'+esc(x.name)+'\"'+(x.name===cur?' selected':'')+'>'+esc(x.name)+'</option>'\n      ).join('');\n      if (sel.options.length > 0 && !(cur && dbs.some(x => x.name === cur))) { sel.selectedIndex = 0; }\n      note.textContent = '服务器 ' + esc(d.server) + ' · 共 ' + dbs.length + ' 个账套' + (src==='fallback'?'（已用保存配置）':'');\n      note.style.color = \"#22c55e\";\n    } else {\n      sel.innerHTML = '<option value=\"\">（无法加载账套列表）</option>';\n      note.textContent = d.error || '连接失败';\n      note.style.color = \"#ef4444\";\n    }\n  };\n  // 有密码时优先用界面参数；失败则自动回退到 GET（后端保存的配置）\n  if (sv && us && pw) {\n    try {\n      const r = await fetch(\"/api/databases\", {\n        method: \"POST\",\n        headers: {\"Content-Type\":\"application/json\"},\n        body: JSON.stringify({ server: sv, user: us, password: pw })\n      });\n      const raw = await r.json();\n      const d = raw.ok ? raw : (raw.databases ? { ok: true, ...raw } : { ok: false, error: raw.error || '连接失败' });\n      if (d.ok) { apply(d, 'post'); return; }\n      // POST 失败，回退到 GET\n      console.log('[刷新] POST 失败，回退到保存配置:', d.error);\n    } catch (e) { console.log('[刷新] POST 请求异常:', e.message); }\n  }\n  try {\n    const r = await fetch(\"/api/databases\");\n    const d = await r.json();\n    // GET 响应没有 ok 字段，有 databases 数组即视为成功\n    apply(d.databases ? { ok: true, ...d } : { ok: false, error: d.error || '连接失败' }, 'fallback');\n  } catch (e) {\n    note.textContent = '请求失败: ' + e.message;\n    note.style.color = \"#ef4444\";\n  }\n};\n\ndocument.getElementById(\"btnTestConn\").onclick = async () => {\n  const sv = document.getElementById(\"connServer\").value.trim();\n  const us = document.getElementById(\"connUser\").value.trim();\n  const pw = document.getElementById(\"connPass\").value;\n  const dbSel = document.getElementById(\"connDbSel\");\n  // 切服务器后先拉该服务器账套并回填偏好\n  await onServerChanged();\n  const db = dbSel.value;\n  if (!sv || !us) { alert('请填写服务器和账号'); return; }\n  // 密码为空时，POST 体不带 password，后端用保存的配置兜底\n  const status = document.getElementById(\"connMetaNote\");\n  status.style.color = \"\"; status.textContent = '连接中...';\n  // 用界面输入的完整参数测试（可连任意服务器）\n  let r;\n  try {\n    const resp = await fetch('/api/test-conn', {method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({server:sv, user:us, password:pw, database:db})});\n    r = await resp.json();\n  } catch(e) { r = {ok:false, error:e.message}; }\n  if (r.ok) {\n    status.textContent = '连接成功，正在应用并重载...';\n    status.style.color = '#22c55e';\n    // 后端 test-conn 已写配置+重连主池；现在切账套 + 重拉字典 + 刷 banner，一步到位\n    await initDbConn();\n    if (db) {\n      const sw = await window.chuanzhi.switchDb({ database: db });\n      if (sw.ok) { window.__curDb = db; await initDbConn(); }\n    }\n    await loadConnBanner();\n    await init().catch(()=>{});  // 重拉单据字典\n    // 持久化（下次启动默认连这个）\n    await window.chuanzhi.saveConfig({ server: sv, user: us, password: pw, database: db });\n    rememberCred();\n    status.textContent = '连接成功';\n  } else {\n    status.textContent = '连接失败: ' + (r.error || '未知错误') + (r.hint ? ' ' + r.hint : '');\n    status.style.color = '#ef4444';\n  }\n};;\n\n// 账套切换：直接 switchDb + 刷新列表/banner，不走「测试连接」整条链路，避免 ensure 覆盖手动选择\ndocument.getElementById(\"connDbSel\").onchange = async () => {\n  const db = document.getElementById(\"connDbSel\").value;\n  const note = document.getElementById(\"connMetaNote\");\n  note.textContent = '切换账套中...'; note.style.color = '';\n  if (db) {\n    const sw = await window.chuanzhi.switchDb({ database: db });\n    if (sw.ok) { window.__curDb = db; await initDbConn(); await loadConnBanner(); note.textContent = '已切换到 ' + db; note.style.color = '#22c55e'; }\n    else { note.textContent = '切换失败: ' + (sw.error||'未知'); note.style.color = '#ef4444'; }\n  }\n};\n\nconst _reconBtn = document.getElementById(\"btnReconnect\");\nif(_reconBtn){_reconBtn.onclick = async () => {\n  _reconBtn.disabled = true; _reconBtn.textContent = \"连接中...\";\n  const status = document.getElementById('status');\n  try {\n    const cfg = await (await fetch('/api/config')).json();\n    if (!cfg.server) {\n      if (status) { status.className = 'status'; status.textContent = '请先填写服务器、账号、密码'; }\n      return;\n    }\n    await init();\n    loadConnBanner();\n  } catch (e) {\n    if (status) { status.className = 'status err'; status.textContent = '加载单据字典失败：' + e.message; }\n  } finally {\n    _reconBtn.disabled = false; _reconBtn.textContent = \"重新连接\";\n  }\n};}\n\n// ---- initial load sequence ----\n// 1. Load database list + banner first (so user sees connection state immediately)\n// 2. Then load document/source metadata in the background\n(async function boot(){\n  let cfgData = {};\n  try {\n    // 启动时先读「保存配置」写入的 config.js，它是表单回填的权威来源\n    try { cfgData = (await (await fetch('/api/config')).json()) || {}; } catch (_) { cfgData = {}; }\n    if (cfgData.backupDir) window.__backupDir = cfgData.backupDir;\n\n    let initMeta;\n    try { initMeta = await (await fetch('/api/meta')).json(); } catch(_) { initMeta = {}; }\n    // 即使 /api/meta 连接成功，也用保存的配置补齐服务器/账号/密码\n    if (cfgData.server || cfgData.user || cfgData.password) {\n      initMeta = {\n        ...initMeta,\n        server: cfgData.server || initMeta.server || '',\n        user: cfgData.user || initMeta.user || '',\n        password: cfgData.password || initMeta.password || ''\n      };\n    }\n    let _creds={}; try{ const cr=await (await fetch('/api/creds')).json(); if(cr&&cr.ok){ _creds=cr.data||{}; window.__creds=_creds; } }catch(_){}\n    // 启动时立即刷 banner + 账套列表（只建一次连接，不额外触发测试连接）\n    await initDbConn();\n    await loadConnBanner();\n    // 加载按服务器的账套偏好（prefs），供切服务器时自动回填手选账套\n    window.__prefs = (_creds.prefs && typeof _creds.prefs==='object') ? _creds.prefs : {};\n    // 若 _lastServer 有偏好账号密码，启动时默认填它（“上次保存的数据库”）\n    const _lastSvr = _creds._lastServer;\n    // 服务器 + 账号 + 密码 一起带出：优先按当前服务器匹配凭据，匹配不到用 _last\n    (function fillAll(){\n      const inp=document.getElementById('connServer'); const u=document.getElementById('connUser'); const pw=document.getElementById('connPass');\n      if(!inp) return;\n      const sv=initMeta.server||'';\n      if(sv && !inp.value){ inp.value=sv; }\n      // 优先用 config.js（\"保存配置\"的权威值），再兜底 creds.json\n      let c=null;\n      if(initMeta.user || initMeta.password){ c={user:initMeta.user||'', pass:initMeta.password||''}; }\n      else { c=(sv && _creds[sv]) || _creds['_last'] || null; }\n      if(c){ if(u&&c.user)u.value=c.user; if(pw&&c.pass)pw.value=c.pass; }\n      // 若当前服务器有保存的偏好账套，选中它（“上次手选”的账套）\n      const pP = sv && window.__prefs[sv];\n      if(pP && pP.db){ try{ const sel=document.getElementById('connDbSel'); const opts=[].slice.call(sel.options); const m=opts.find(o=>o.value===pP.db); if(m){ sel.value=pP.db; } }catch(_){} }\n    })();\n\n    // 关键修复：把 creds.json（磁盘记忆）里已保存的所有服务器并入下拉历史，\n    // 这样即使 localStorage 被重置/换电脑，下拉也永不为空、▼ 一展开就可见\n    try{\n      let h=getSrvHist();\n      for(const k in _creds){ if(k==='_last') continue; if(h.indexOf(k)<0){ h.push(k); } }\n      h=Array.from(new Set(h)).slice(0,10);\n      localStorage.setItem('momo_svr_hist', JSON.stringify(h));\n    }catch(_){}\n  } catch (e) {\n    console.error('db init error:', e);\n    const txt=document.getElementById('connBannerText');\n    const el=document.getElementById('connBanner');\n    if(txt && el){ el.className='err'; txt.innerHTML='<b style=\"color:#ef4444\">初始化失败</b>：'+esc(e.message)+'。请点\"重新连接\"。'; }\n  }\n  // 没有保存服务器时不做字典加载，避免首次打开显示\"字典加载失败\"\n  if (cfgData.server) {\n    init().catch(e => {\n      console.error('meta load error:', e);\n      const status=document.getElementById('status');\n      if(status){ status.className='status err'; status.textContent='加载单据字典失败：'+e.message; }\n    });\n  } else {\n    const status=document.getElementById('status');\n    if(status){ status.className='status'; status.textContent='等待数据库连接后加载单据字典'; }\n  }\n\n  (function(){\n    const sv=document.getElementById('connServer');\n    if(!sv) return;\n    sv.addEventListener('input', function(){ applyCred(sv.value.trim()); });\n    sv.addEventListener('change', function(){ rememberSrv(); applyCred(sv.value.trim()); onServerChanged(); });\n  })();\n\n  // 首次打开提示：应用内弹窗（不使用原生 alert，避免关闭后窗口失焦无法输入）\n  try {\n    const fo = await (await fetch('/api/first-open')).json();\n    if (fo && fo.ok && !fo.seen) {\n      await fetch('/api/first-open', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' });\n      const modal = document.getElementById('firstOpenModal');\n      if (modal) {\n        modal.style.display = 'flex';\n        const ok = document.getElementById('firstOpenOk');\n        if (ok) ok.focus();\n      }\n    }\n  } catch (e) {}\n})();\n\n// ---- 高级选项 展开/收起 ----\n\n// ---- 触发器面板 展开/收起 ----\ndocument.getElementById(\"trigPanelTitle\").onclick = () => {\n  const body = document.getElementById(\"trigPanelBody\");\n  const title = document.getElementById(\"trigPanelTitle\");\n  const showing = body.style.display !== \"none\";\n  if (showing) {\n    body.style.display = \"none\";\n    title.textContent = \"▼ 已建立触发器（点击展开）\";\n  } else {\n    body.style.display = \"\";\n    title.textContent = \"▲ 已建立触发器（点击收起）\";\n    if (typeof window.refreshTrigList === 'function') window.refreshTrigList();\n  }\n};\n\n// ---- 保存配置 ----\n// ---- 备份路径：按钮弹出原生目录选择框，选完立即写入配置 ----\nasync function loadBackupDir() {\n  try {\n    const r = await fetch('/api/backup-dir');\n    const d = await r.json();\n    const el = document.getElementById('backupDirNote');\n    if (el) el.textContent = '备份路径：' + (d.backupDir || '未设置');\n    window.__backupDir = d.backupDir || '';\n  } catch (_) {}\n}\n\ndocument.getElementById('btnBackupDir').onclick = async () => {\n  const btn = document.getElementById('btnBackupDir');\n  const note = document.getElementById('backupDirNote');\n  const oldText = btn.textContent;\n  btn.disabled = true;\n  btn.textContent = '选择中...';\n  try {\n    const r = await fetch('/api/backup-dir', {\n      method: 'POST',\n      headers: {'Content-Type':'application/json'},\n      body: '{}'\n    });\n    const d = await r.json();\n    if (d.ok && d.canceled) {\n      if (note) note.textContent = '备份路径：' + (d.backupDir || '未设置');\n    } else if (d.ok && d.backupDir) {\n      window.__backupDir = d.backupDir;\n      if (note) note.textContent = '备份路径：' + d.backupDir;\n    } else {\n      alert(d.error || '设置备份路径失败');\n    }\n  } catch (e) {\n    alert('打开目录选择框失败: ' + e.message);\n  } finally {\n    btn.disabled = false;\n    btn.textContent = oldText;\n  }\n};\n\nloadBackupDir();\n\ndocument.getElementById(\"btnSaveConfig\").onclick = async () => {\n  const server = document.getElementById(\"connServer\").value.trim();\n  const user = document.getElementById(\"connUser\").value.trim();\n  const password = document.getElementById(\"connPass\").value;\n  const database = document.getElementById(\"connDbSel\").value; // 当前选中的账套，随配置一起持久化\n  const note = document.getElementById(\"connMetaNote\");\n  note.textContent = \"保存中...\";\n  rememberSrv(); // 记入服务器历史，下次可在下拉里直接选\n  rememberCred(); // 立即保存凭据到本地记忆，不必等接口\n  note.style.color = \"\";\n  try {\n    const r = await fetch(\"/api/save-config\", {\n      method: \"POST\",\n      headers: {\"Content-Type\":\"application/json\"},\n      body: JSON.stringify({server, user, password, database})\n    });\n    const d = await r.json();\n    if (d.ok) {\n      // 保存配置 = 权威来源：把当前界面填的 服务器/账号/密码 写进 creds.json（含 _last），重启即还原\n      try{ await fetch('/api/creds/save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({[server]:{user:user,pass:password},_last:{user:user,pass:password}})}); }catch(_){}\n      note.textContent = \"配置已保存，重启后自动使用；需要立即切换请点「测试连接」\";\n      note.style.color = \"#22c55e\";\n    } else {\n      note.textContent = \"保存失败: \" + (d.error || \"未知错误\");\n      note.style.color = \"#ef4444\";\n    }\n  } catch (e) {\n    note.textContent = \"保存失败: \" + e.message;\n    note.style.color = \"#ef4444\";\n  }\n};\n</script>\n<script>\n// ---- 密码显示/隐藏切换 ----\n(function(){\n  const btn = document.getElementById('btnTogglePass');\n  const input = document.getElementById('connPass');\n  if (!btn || !input) return;\n  let userSetText = false;\n  btn.addEventListener('click', function(){\n    userSetText = !userSetText;\n    input.type = userSetText ? 'text' : 'password';\n    btn.textContent = userSetText ? '隐藏' : '显示';\n  });\n})();\n</script>\n\n<script>\n// ---- 触发器管理 ----\n(function(){\nfunction escT(x){return String(x==null?\"\":x).replace(/[&<>\"]/g,c=>({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",\"\\\"\":\"&quot;\"}[c]));}\n\nfunction chainRow(){\n  const d=document.createElement(\"div\");\n  d.className=\"chainrow\";\n  d.innerHTML='<input class=\"chT\" type=\"text\" placeholder=\"来源表 (如 TPADEA)\"><input class=\"chL\" type=\"text\" placeholder=\"关联列 left (如 DEA008)\"><input class=\"chR\" type=\"text\" placeholder=\"关联列 right (如 LOA002)\"><input class=\"chV\" type=\"text\" placeholder=\"取值列 (如 LOA003)\"><button class=\"btn sm danger\" type=\"button\">删</button>';\n  const del=d.querySelector(\"button\");\n  del.onclick=()=>d.remove();\n  const _cr=document.getElementById(\"chainRows\"); if(_cr) _cr.appendChild(d);\n}\n\nfunction readChain(){\n  return [...document.querySelectorAll(\"#chainRows .chainrow\")]\n    .map(r=>({\n      tbl:r.querySelector(\".chT\").value.trim(),\n      joinCols:[{left:r.querySelector(\".chL\").value.trim(), right:r.querySelector(\".chR\").value.trim()}],\n      valueCol:r.querySelector(\".chV\").value.trim()\n    }))\n    .filter(r=>r.tbl);\n}\n\nfunction statusEl(){ const el=document.getElementById(\"trigStatus\"); if(!el){ const d=document.createElement(\"span\"); d.id=\"trigStatus\"; d.className=\"status\"; document.getElementById(\"trigList\").before(d);} return document.getElementById(\"trigStatus\"); }\n\nasync function refreshTrigList(){\n  const el=document.getElementById(\"trigList\");\n  el.innerHTML='<div class=\"sub\">加载中...</div>';\n  const r=await window.chuanzhi.listTriggers();\n  if(!r.ok){ el.innerHTML='<div class=\"status err\">'+escT(r.error)+'</div>'; return; }\n  const t=(r.data&&r.data.triggers)||[];\n  const dbNote=document.getElementById('trigDbNote');\n  if(dbNote && r.data) dbNote.textContent='当前账套：'+(r.data.database||'-')+' · 服务器：'+(r.data.server||'-');\n  if(!t.length){ el.innerHTML='<div class=\"sub\">当前数据库没有触发器</div>'; return; }\n\n  const toolTrigs = t.filter(x=>x.isTool);\n  const sysTrigs  = t.filter(x=>!x.isTool);\n\n  const rowHtml = (x)=>{\n    const badge = x.disabled ? '<span class=\"badge off\">已停用</span>' : '<span class=\"badge on\">启用中</span>';\n    const descHtml = x.desc ? '<div class=\"sub\" style=\"margin-top:2px\">'+escT(x.desc)+'</div>' : '';\n    return '<tr><td><b>'+escT(x.name)+'</b>'+descHtml+'</td>'\n      + '<td style=\"font-family:Consolas,monospace\">'+escT(x.tbl)+'</td>'\n      + '<td>'+badge+'</td>'\n      + '<td style=\"white-space:nowrap\">'\n      + '<button class=\"btn sm\" data-act=\"toggle\" data-n=\"'+escT(x.name)+'\" data-en=\"'+(x.disabled?1:0)+'\" style=\"margin-right:4px\">'+(x.disabled?'启用':'停用')+'</button>'\n      + '<button class=\"btn sm danger\" data-act=\"drop\" data-n=\"'+escT(x.name)+'\">删除</button>'\n      + '</td></tr>';\n  };\n\n  let body='<table class=\"trig-table\"><thead><tr><th>名称 / 作用</th><th>挂载表</th><th>状态</th><th>操作</th></tr></thead><tbody>'\n    + (toolTrigs.length ? toolTrigs.map(rowHtml).join('') : '<tr><td colspan=\"4\" class=\"sub\">暂无本工具建立的触发器</td></tr>')\n    + '</tbody></table>';\n\n  if(sysTrigs.length){\n    body+='<details style=\"margin-top:10px\"><summary style=\"cursor:pointer;color:#94a3b8;font-size:12px\">系统默认触发器（'+sysTrigs.length+' 个，点击展开）</summary>'\n      + '<table class=\"trig-table\" style=\"margin-top:8px\"><thead><tr><th>名称 / 作用</th><th>挂载表</th><th>状态</th><th>操作</th></tr></thead><tbody>'\n      + sysTrigs.map(rowHtml).join('')\n      + '</tbody></table></details>';\n  }\n  el.innerHTML=body;\n\n  el.querySelectorAll('button[data-act=\"toggle\"]').forEach(b=>{\n    b.onclick=async()=>{\n      const r2=await window.chuanzhi.toggleTrigger({trgName:b.dataset.n, enable:b.dataset.en===\"1\"});\n      statusEl().className=\"status \"+(r2.ok?\"ok\":\"err\");\n      statusEl().textContent=r2.ok?(\"已\"+(r2.data.enabled?\"启用\":\"停用\")+\" \"+b.dataset.n):r2.error;\n      refreshTrigList();\n    };\n  });\n  el.querySelectorAll('button[data-act=\"drop\"]').forEach(b=>{\n    b.onclick=async()=>{\n      const curDb2=document.getElementById('connDbSel')?document.getElementById('connDbSel').value:'DSB';\n      if(!confirm(\"确认删除触发器 \"+b.dataset.n+\"？会先自动备份到 \"+(window.__backupDir||\"D:\\\\TPA\\\\SQL2008\")))return;\n      const r2=await window.chuanzhi.dropTrigger({trgName:b.dataset.n, confirm:true});\n      statusEl().className=\"status \"+(r2.ok?\"ok\":\"err\");\n      statusEl().textContent=r2.ok?(\"已删除（备份 \"+r2.data.backupPath+\"）\"):r2.error;\n      refreshTrigList();\n    };\n  });\n}\nfunction curTgReq(){\n  return {\n    trgName:document.getElementById(\"tgName\").value.trim(),\n    onTable:document.getElementById(\"tgOnTable\").value.trim(),\n    tgtTable:document.getElementById(\"tgTgtTable\").value.trim(),\n    tgtCol:document.getElementById(\"tgTgtCol\").value.trim(),\n    chain:readChain(),\n    mode:document.getElementById(\"tgForce\").checked?\"force\":\"fill\"\n  };\n}\n\nwindow.refreshTrigList = refreshTrigList;\ndocument.getElementById(\"trigRefresh\").onclick=refreshTrigList;\nconst _bac=document.getElementById(\"btnAddChain\"); if(_bac) _bac.onclick=()=>chainRow();\n\n(function(){const _bfb=document.getElementById(\"btnTgBuild\"); if(_bfb) _bfb.onclick=async()=>{\n  const b=curTgReq();\n  if(!b.trgName||!b.onTable||!b.tgtTable||!b.tgtCol||!b.chain.length){\n    statusEl().className=\"status err\";\n    statusEl().textContent=\"请填写完整：触发器名、挂载表、目标列、以及至少一行取值链\";\n    return;\n  }\n  statusEl().className=\"status\";\n  statusEl().textContent=\"预览中...\";\n  const r=await window.chuanzhi.buildTrigger(b);\n  const st=statusEl();\n  const box=document.getElementById(\"trigResult\");\n  if(!r.ok){ st.className=\"status err\"; st.textContent=r.error; return; }\n  st.className=\"status ok\"; st.textContent=\"映射检查完成，点「创建」建立触发器。\";\n  box.innerHTML='';\n};\n})();\n\n(function(){const _bfc=document.getElementById(\"btnTgCreate\"); if(_bfc) _bfc.onclick=async()=>{\n  const b=curTgReq();\n  if(!b.trgName||!b.onTable||!b.tgtTable||!b.tgtCol||!b.chain.length){\n    statusEl().className=\"status err\";\n    statusEl().textContent=\"请填写完整后再创建\";\n    return;\n  }\n  statusEl().className=\"status\"; statusEl().textContent=\"构建中...\";\n  const tr=await window.chuanzhi.buildTrigger(b);\n  if(!tr.ok){ statusEl().className=\"status err\"; statusEl().textContent=tr.error; return; }\n  if(!confirm(\"确认创建触发器？会先自动备份到 \"+(window.__backupDir||\"D:\\\\TPA\\\\SQL2008\")))return;\n  const r=await window.chuanzhi.createTrigger({trgName:b.trgName, onTable:b.onTable, trigSql:tr.data.triggerSql, confirm:true});\n  statusEl().className=\"status \"+(r.ok?\"ok\":\"err\");\n    statusEl().textContent=r.ok?(\"已创建 \"+r.data.name+\" · 数据库 \"+(r.data.database||\"-\")+\" · 备份 \"+r.data.backupPath):r.error;\n  refreshTrigList();\n};\n})();\n\nchainRow();\n})();\n</script>\n<script>\n(function(){\n  const m=document.getElementById('firstOpenModal');\n  const b=document.getElementById('firstOpenOk');\n  if(b) b.onclick=function(){\n    if(m) m.style.display='none';\n    const s=document.getElementById('connServer');\n    if(s){ try{ s.focus(); }catch(_){} }\n  };\n})();\n</script>\n</body>\n</html>\n";
